import type { BeerEvolutionBreakdownData } from '../../../../types';

export const isBeerEvolutionBreakdownDataAligned = (
  data: BeerEvolutionBreakdownData,
  columnCount: number,
  valuesLength: number,
): boolean => {
  if (columnCount === 0 || valuesLength !== columnCount) {
    return false;
  }

  const formattedRowLength = data.formattedData?.[0]?.length;
  if (formattedRowLength !== undefined && formattedRowLength !== columnCount) {
    return false;
  }

  const imageCount = data.images?.data?.length ?? 0;
  if (imageCount > 0 && imageCount !== columnCount) {
    return false;
  }

  const comparisonRows = data.comparisonLine?.data;
  if (comparisonRows?.length) {
    return comparisonRows.every((row) => row.data?.length === columnCount);
  }

  return true;
};
